def two_sum(nums: list[int], target: int) -> tuple[int, int]:
    index_of: dict[int, int] = {}
    for i, num in enumerate(nums):
        partner = target - num
        if partner in index_of:
            return index_of[partner], i
        index_of[num] = i
    return -1, -1


