const input = readFileSync(0, "utf8");

function twoSum(nums: number[], target: number): [number, number] {
  const indexOf = new Map<number, number>();
  for (const [i, num] of nums.entries()) {
    const j = indexOf.get(target - num);
    if (j !== undefined) {
      return [j, i];
    }
    indexOf.set(num, i);
  }
  return [-1, -1];
}

